const fs = require('fs');
const path = require('path');

const servicesDir = path.join(__dirname, 'services');
const files = fs.readdirSync(servicesDir).filter(f => f.endsWith('.html'));

files.forEach(file => {
    const filePath = path.join(servicesDir, file);
    let html = fs.readFileSync(filePath, 'utf8');

    // Fix paragraph alignment in the overview section
    // Currently they are `<p style="color:var(--text-muted);line-height:1.9;margin-bottom:18px;font-size:0.97rem">`
    // We want to add `text-align:left;` to them
    
    // We only want to target the overview section paragraphs
    const overviewRegex = /(<section class="section" id="wa-overview">[\s\S]*?)(<\/div>\s*<div class="stat-card-container")/i;
    
    // Wait, whatsapp-marketing.html has <div class="" data-aos="fade-up"> instead of stat-card-container
    // Let's just replace all paragraphs that match that specific style string globally in these files
    // It's safe since they are all generated by us
    
    html = html.replace(/<p style="color:var\(--text-muted\);line-height:1\.9;margin-bottom:18px;font-size:0\.97rem">/g, '<p style="color:var(--text-muted);line-height:1.9;margin-bottom:18px;font-size:0.97rem;text-align:left;">');
    html = html.replace(/<p style="color:var\(--text-muted\);line-height:1\.9;font-size:0\.97rem">/g, '<p style="color:var(--text-muted);line-height:1.9;font-size:0.97rem;text-align:left;">');

    fs.writeFileSync(filePath, html, 'utf8');
    console.log(`Fixed alignment in: ${file}`);
});
console.log("All text alignment fixes applied.");
